#!/usr/bin/env python3
"""Generate ui/Grassfield/Ui/Tokens.qml, and the compositor plugin's token header, from ui/tokens/tokens.json (stdlib only).

Usage: gen-tokens.py [--check]
  --check  do not write; exit 1 if a generated file is stale.

The compositor plugin draws with its own renderer: the groups in PLUGIN_GROUPS are also written as C++ constants to
compositor/src/core/ThemeTokens.hpp (numbers, and colours as 0xRRGGBB), read by compositor/src/core/Theme.hpp (ADR-0003:
one source of values for both renderers; ADR-0015).
"""
import json
import pathlib
import re
import sys

UI = pathlib.Path(__file__).resolve().parent.parent
SRC = UI / "tokens" / "tokens.json"
DST = UI / "Grassfield" / "Ui" / "Tokens.qml"
PLUGIN_DST = UI.parent / "compositor" / "src" / "core" / "ThemeTokens.hpp"
PLUGIN_GROUPS = ("titlebar", "window")  # window: the lights the apps draw (ADR-0015 P7, one token source)


def is_leaf(node):
    return isinstance(node, dict) and "value" in node


def qml_literal(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    return json.dumps(value)


def qml_type(value):
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "real"
    if isinstance(value, str):
        return "string"
    return "var"


def camel(*parts):
    first, *rest = parts
    return first + "".join(p[:1].upper() + p[1:] for p in rest)


def generate(data):
    out = [
        "pragma Singleton",
        "// GENERATED by ui/tools/gen-tokens.py from ui/tokens/tokens.json. Do not edit.",
        "import QtQml",
        "",
        "QtObject {",
        f"    readonly property int version: {data['version']}",
    ]
    for group, body in data.items():
        if group in ("version", "_note"):
            continue
        if group == "color":
            for appearance, roles in body.items():
                out.append("")
                out.append(f"    // color roles, {appearance} appearance")
                out.append(f"    readonly property var {camel('color', appearance)}: ({{")
                items = list(roles.items())
                for i, (role, leaf) in enumerate(items):
                    comma = "," if i < len(items) - 1 else ""
                    out.append(f"        {role}: {qml_literal(leaf['value'])}{comma}  // {leaf['source']}")
                out.append("    })")
            continue
        out.append("")
        for name, leaf in body.items():
            if not is_leaf(leaf):
                raise SystemExit(f"tokens.json: {group}.{name} is not a {{value, source}} leaf")
            v = leaf["value"]
            expr = qml_literal(v)
            typ = qml_type(v)
            # Optional leaf keys make a token follow an Appearance setting (Settings > Accessibility > Display):
            #   "textScale": true        the size is scaled by Appearance.textScale and rounded (Text Size)
            #   "increaseContrast": V    the value is V while Appearance.increaseContrast is on (Increase Contrast)
            if leaf.get("textScale"):
                expr = f"Math.round({expr} * Appearance.textScale)"
                typ = "int"
            if "increaseContrast" in leaf:
                expr = f"Appearance.increaseContrast ? {qml_literal(leaf['increaseContrast'])} : {expr}"
            out.append(f"    // {leaf['source']}")
            out.append(f"    readonly property {typ} {camel(group, name)}: {expr}")
    out.append("}")
    return "\n".join(out) + "\n"


def cpp_constant(group, name, value):
    """One C++ constant of a plugin token: kGroupName, int / double / 0xRRGGBB colour."""
    ident = "k" + camel(group, name)[:1].upper() + camel(group, name)[1:]
    if isinstance(value, bool):
        return f"inline constexpr bool {ident} = {'true' if value else 'false'};"
    if isinstance(value, int):
        return f"inline constexpr int {ident} = {value};"
    if isinstance(value, float):
        return f"inline constexpr double {ident} = {value!r};"
    if isinstance(value, str) and re.fullmatch(r"#[0-9A-Fa-f]{6}", value):
        return f"inline constexpr uint32_t {ident} = 0x{value[1:].upper()};"
    raise SystemExit(f"tokens.json: {group}.{name}: a plugin token is a number or a #rrggbb colour")


def generate_plugin(data):
    out = [
        "#pragma once",
        "",
        "// GENERATED by ui/tools/gen-tokens.py from ui/tokens/tokens.json. Do not edit.",
        "// The design tokens the compositor plugin draws with (read by core/Theme.hpp; no Hyprland include).",
        "",
        "#include <cstdint>",
        "",
        "namespace gf::theme::tokens {",
    ]
    for group in PLUGIN_GROUPS:
        body = data.get(group)
        if not isinstance(body, dict):
            raise SystemExit(f"tokens.json: plugin group {group} is missing")
        for name, leaf in body.items():
            if not is_leaf(leaf):
                raise SystemExit(f"tokens.json: {group}.{name} is not a {{value, source}} leaf")
            out.append(f"    // {leaf['source']}")
            out.append(f"    {cpp_constant(group, name, leaf['value'])}")
    out.append("} // namespace gf::theme::tokens")
    return "\n".join(out) + "\n"


def main():
    data = json.loads(SRC.read_text())
    outputs = ((DST, generate(data), "ui/Grassfield/Ui/Tokens.qml"), (PLUGIN_DST, generate_plugin(data), "compositor/src/core/ThemeTokens.hpp"))
    if "--check" in sys.argv[1:]:
        stale = [label for path, text, label in outputs if not path.exists() or path.read_text() != text]
        for label in stale:
            print(f"gen-tokens: {label} is stale; run ui/tools/gen-tokens.py", file=sys.stderr)
        if stale:
            return 1
        print("gen-tokens: up to date")
        return 0
    for path, text, label in outputs:
        path.write_text(text)
        print(f"gen-tokens: wrote {label}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
